package glitch

import data.glitch_lib

# Sensitive field patterns for hardcoded passwords
sensitive_fields := {
    "password", "passwd", "pwd", "secret", "secretkey", "secret_key",
    "credentials", "creds", "token", "apitoken", "accesstoken", "authtoken",
    "auth", "authentication", "privatekey", "private_key", "certificate",
    "cert", "clientcert", "connectionstring", "connection_string", "connstr",
    "defaultpassword", "initialpassword", "adminpassword"
}

# Weak password patterns
weak_passwords := {"password", "123456", "admin", "default", "secret", "changeme", "root"}

# Check if field name is sensitive
is_sensitive_field(name) {
    lower := lower(name)
    lower == sensitive_fields[_]
}

is_sensitive_field(name) {
    lower := lower(name)
    endswith(lower, "_password")
}

is_sensitive_field(name) {
    lower := lower(name)
    endswith(lower, "_secret")
}

is_sensitive_field(name) {
    lower := lower(name)
    endswith(lower, "_token")
}

is_sensitive_field(name) {
    lower := lower(name)
    endswith(lower, "_key")
}

# Check if value is a hardcoded string (not a reference to external secret store)
is_hardcoded_string(value) {
    value.ir_type == "String"
    count(value.value) > 0
    not is_secret_reference(lower(value.value))
}

is_hardcoded_string(value) {
    value.ir_type == "Integer"
}

# Check if string looks like base64 encoded (common obfuscation)
is_base64_like(value) {
    regex.match("^[A-Za-z0-9+/]{20,}={0,2}$", value)
    not is_secret_reference(lower(value))
}

# Check if value references external secret store
is_secret_reference(str) {
    contains(str, "vault")
}

is_secret_reference(str) {
    contains(str, "keyvault")
}

is_secret_reference(str) {
    contains(str, "secretsmanager")
}

is_secret_reference(str) {
    contains(str, "parameterstore")
}

is_secret_reference(str) {
    contains(str, "secretref")
}

is_secret_reference(str) {
    contains(str, "managed_identity")
}

is_secret_reference(str) {
    contains(str, "service_account")
}

# Check if string contains weak password pattern
is_weak_password(str) {
    lower := lower(str)
    lower == weak_passwords[_]
}

# Recursively check values in complex structures for hardcoded secrets
check_value_for_secret(value) {
    is_hardcoded_string(value)
}

check_value_for_secret(value) {
    value.ir_type == "Array"
    item := value.value[_]
    check_value_for_secret(item)
}

check_value_for_secret(value) {
    value.ir_type == "Hash"
    val := value.value[_]
    check_value_for_secret(val)
}

# Main detection: hardcoded password in atomic unit attributes
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    is_sensitive_field(attr.name)
    check_value_for_secret(attr.value)

    result := {
        "type": "sec_hard_pass",
        "element": attr,
        "path": parent.path,
        "description": "Use of Hard-coded Password - Passwords or secrets should not be hardcoded in configuration files. Use secure external stores like vaults or key management services. (CWE-259)"
    }
}

# Detection: hardcoded password in variables
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    vars := glitch_lib.all_variables(parent)
    var := vars[_]

    is_sensitive_field(var.name)
    check_value_for_secret(var.value)

    result := {
        "type": "sec_hard_pass",
        "element": var,
        "path": parent.path,
        "description": "Use of Hard-coded Password - Passwords or secrets should not be hardcoded in configuration files. Use secure external stores like vaults or key management services. (CWE-259)"
    }
}

# Detection: weak/obvious password values
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    is_sensitive_field(attr.name)
    attr.value.ir_type == "String"
    is_weak_password(attr.value.value)

    result := {
        "type": "sec_hard_pass",
        "element": attr,
        "path": parent.path,
        "description": "Use of Weak Hard-coded Password - Weak or obvious passwords should not be used even in configuration files. Use secure external stores with strong credentials. (CWE-259)"
    }
}

# Detection: base64 encoded secrets (obfuscation attempt)
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    is_sensitive_field(attr.name)
    attr.value.ir_type == "String"
    is_base64_like(attr.value.value)

    result := {
        "type": "sec_hard_pass",
        "element": attr,
        "path": parent.path,
        "description": "Use of Obfuscated Hard-coded Password - Base64 encoding does not provide security. Secrets should be retrieved from secure external stores. (CWE-259)"
    }
}

